import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
capacity = None
for rec in records:
    vals = rec.get('values', {})
    if 'Capacity' in vals:
        capacity = int(vals['Capacity'])
        break
if capacity is None:
    raise ValueError('Capacity not found in LEGACY_RECORDS.')
products = []
values = {}
weights = {}
for rec in records:
    vals = rec.get('values', {})
    if 'ProductName' in vals:
        pname = vals['ProductName']
        products.append(pname)
        if 'Value' not in vals or 'Weight' not in vals:
            raise ValueError(f'Missing Value or Weight for product {pname}')
        values[pname] = int(vals['Value'])
        weights[pname] = int(vals['Weight'])
if len(products) != 24:
    raise ValueError('Expected 24 products, got {}'.format(len(products)))
if set(values.keys()) != set(products) or set(weights.keys()) != set(products):
    raise ValueError('Mismatch in product keys for values/weights.')
m = gp.Model('vehicle_inventory')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[p] * x[p] for p in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weights[p] * x[p] for p in products)) <= capacity, name='cap')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
